CREATE   VIEW [FO].[vwDebtorDaysRevenue] AS

SELECT
	 RICINVOICETYPE AS 'Invoice Type'
	,SUM(CTR.AMOUNTCUR) AS RevenueCUR
	,SUM(CTR.AMOUNTMST) AS RevenueMST
FROM [synapse_fo].[CUSTTRANS_RICS] CTR
WHERE TRANSTYPE IN (2)
	AND TRANSDATE >= DATEADD(d, -365, CAST(GETDATE() -1 AS DATE)) 
	AND TRANSDATE < CAST(GETDATE() -1 AS DATE)
GROUP BY RICINVOICETYPE
